page.css:
:root{
  --blue:#0088C0; --teal:#00A890; --ink:#0A3A52; --deep:#072A3D;
  --grey:#5A6B73; --mute:#7C8B92; --tintb:#EAF5FB; --tintt:#E5F6F1;
  --sand:#F7FAFC; --line:#DCE7ED; --white:#fff;
  --blue-d:#0A6C9C; --teal-d:#0A7D68;
  --sans:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --wrap:1160px; --r:14px; --shadow:0 10px 30px rgba(10,58,82,.10);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);color:#22333B;background:var(--white);line-height:1.65;font-size:17px;-webkit-font-smoothing:antialiased}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.narrow{max-width:820px}
h1,h2,h3{color:var(--ink);line-height:1.18;margin:0 0 .5em;font-weight:800;letter-spacing:-.01em}
h1{font-size:clamp(2rem,4.6vw,3.15rem)}
h2{font-size:clamp(1.5rem,3vw,2.15rem)}
h3{font-size:1.16rem}
p{margin:0 0 1rem}
a{color:var(--blue-d)}
img{max-width:100%}
.skip{position:absolute;left:-999px;top:0;background:var(--ink);color:#fff;padding:10px 16px;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0}

/* header */
.site-head{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.96);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
.head-inner{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:74px}
.brand{display:inline-flex;align-items:center}
.logo{height:52px;width:auto;display:block}
.nav{display:flex;align-items:center;gap:6px}
.nav>a,.submenu-btn{color:var(--ink);text-decoration:none;font-weight:600;font-size:.98rem;padding:10px 12px;border-radius:8px;background:none;border:0;cursor:pointer;font-family:inherit}
.nav>a:hover,.submenu-btn:hover{background:var(--tintb);color:var(--blue-d)}
.hasmenu{position:relative}
.submenu-btn{display:inline-flex;align-items:center;gap:6px}
.submenu-btn i{font-size:.7rem}
.submenu{position:absolute;top:100%;left:0;min-width:250px;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);padding:8px;display:none}
.hasmenu:hover .submenu,.hasmenu:focus-within .submenu{display:block}
.submenu a{display:block;padding:9px 12px;border-radius:8px;color:var(--ink);text-decoration:none;font-weight:600;font-size:.94rem}
.submenu a:hover{background:var(--tintt);color:var(--teal-d)}
.nav-cta{background:var(--ink)!important;color:#fff!important;border-radius:999px;padding:10px 16px!important;margin-left:6px}
.nav-cta:hover{background:var(--deep)!important}
.navtoggle{display:none;background:var(--ink);color:#fff;border:0;font-size:1.2rem;width:46px;height:46px;border-radius:10px;cursor:pointer}

/* buttons */
.btn{display:inline-flex;align-items:center;gap:9px;font-weight:700;text-decoration:none;border-radius:999px;padding:14px 26px;font-size:1rem;border:2px solid transparent;cursor:pointer;transition:.15s;font-family:inherit}
.btn-primary{background:var(--ink);color:#fff}
.btn-primary:hover{background:var(--deep);transform:translateY(-1px)}
.btn-ghost{background:#fff;color:var(--ink);border-color:var(--ink)}
.btn-ghost:hover{background:var(--tintb)}
.btn-ghost-dark{background:transparent;color:#fff;border-color:rgba(255,255,255,.7)}
.btn-ghost-dark:hover{background:rgba(255,255,255,.12)}
.btn-outline{background:#fff;color:var(--blue-d);border-color:var(--blue-d)}
.btn-outline:hover{background:var(--tintb)}
.btn-block{width:100%;justify-content:center}

/* hero */
.hero{background:linear-gradient(160deg,var(--tintb) 0%,#fff 55%,var(--tintt) 100%);padding:56px 0 46px;border-bottom:1px solid var(--line)}
.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:44px;align-items:start}
.eyebrow{display:inline-flex;align-items:center;gap:8px;color:var(--teal-d);font-weight:800;text-transform:uppercase;letter-spacing:.09em;font-size:.8rem;margin:0 0 14px}
.hero-copy h1{margin-bottom:.35em}
.lede{font-size:1.16rem;color:#33454D;max-width:34em}
.eeat{list-style:none;padding:0;margin:20px 0 26px;display:grid;grid-template-columns:1fr 1fr;gap:10px 20px}
.eeat li{display:flex;align-items:center;gap:10px;font-weight:600;color:var(--ink);font-size:.98rem}
.eeat i{color:var(--teal);font-size:1.05rem}
.hero-cta{display:flex;gap:12px;flex-wrap:wrap}

/* form */
.enquiry{background:#fff;border:1px solid var(--line);border-top:5px solid var(--teal);border-radius:18px;box-shadow:var(--shadow);padding:26px}
.form-title{font-size:1.4rem;margin:0 0 4px}
.form-sub{color:var(--grey);font-size:.95rem;margin-bottom:16px}
.field{margin-bottom:13px}
.field label{display:block;font-weight:700;color:var(--ink);font-size:.9rem;margin-bottom:5px}
.field .opt{font-weight:500;color:var(--mute)}
.field input,.field select,.field textarea{width:100%;padding:12px 13px;border:1.5px solid var(--line);border-radius:10px;font-size:1rem;font-family:inherit;background:#fff;color:#22333B}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(0,136,192,.35);border-color:var(--blue)}
.form-fine{font-size:.82rem;color:var(--grey);margin:12px 0 0;display:flex;align-items:center;gap:7px}

/* trust strip */
.trust{background:var(--ink);color:#fff}
.trust-row{display:flex;flex-wrap:wrap;justify-content:center;gap:14px 34px;padding:16px 22px}
.trust-row span{display:inline-flex;align-items:center;gap:9px;font-weight:600;font-size:.95rem}
.trust-row i{color:#7FD9C8}

/* bands / rhythm */
.band{padding:60px 0}
.band.alt{background:var(--sand)}
.band.coverage{background:linear-gradient(180deg,#fff, var(--tintb))}
.kicker{color:var(--teal-d);font-weight:800;text-transform:uppercase;letter-spacing:.08em;font-size:.8rem;margin:0 0 8px}
.kicker.light{color:#7FD9C8}
.sec-head{max-width:760px;margin:0 0 34px}
.sec-intro{color:var(--grey);font-size:1.08rem}
.feature-img{padding-top:34px;padding-bottom:0}
.feature-img.slim{padding-top:10px;padding-bottom:40px}
.nifty-image-placeholder{width:100%;height:auto;display:block;border-radius:var(--r)}

/* service cards */
.cards-4{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}
.scard{display:block;background:#fff;border:1px solid var(--line);border-left:5px solid var(--blue);border-radius:14px;padding:26px;text-decoration:none;color:inherit;transition:.15s;box-shadow:0 4px 14px rgba(10,58,82,.05)}
.scard:hover{transform:translateY(-3px);box-shadow:var(--shadow);border-left-color:var(--teal)}
.scard-ic{display:inline-flex;width:52px;height:52px;align-items:center;justify-content:center;background:var(--tintb);color:var(--blue);border-radius:12px;font-size:1.35rem;margin-bottom:14px}
.scard:hover .scard-ic{background:var(--tintt);color:var(--teal)}
.scard h3{margin-bottom:.4em}
.scard p{color:var(--grey);font-size:.98rem}
.scard-more{display:inline-flex;align-items:center;gap:8px;color:var(--blue-d);font-weight:700;font-size:.92rem;margin-top:6px}

/* steps */
.steps{list-style:none;counter-reset:s;padding:0;margin:0;display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.steps li{background:#fff;border:1px solid var(--line);border-radius:14px;padding:24px 22px 22px;position:relative}
.stepno{display:inline-flex;width:44px;height:44px;align-items:center;justify-content:center;background:var(--teal-d);color:#fff;font-weight:800;border-radius:50%;font-size:1.2rem;margin-bottom:14px}
.steps h3{font-size:1.05rem}
.steps p{color:var(--grey);font-size:.95rem;margin:0}

/* split */
.split{display:grid;grid-template-columns:1.05fr .95fr;gap:40px;align-items:center}
.split-img .nifty-image-placeholder{border-radius:18px;box-shadow:var(--shadow)}

/* dark band */
.band.dark{background:var(--ink);color:#EAF2F6}
.band.dark h2{color:#fff}
.band.dark p{color:#C4D6DF}

/* coverage chips */
.chip-key{display:flex;gap:22px;flex-wrap:wrap;margin:0 0 18px;color:var(--grey);font-size:.9rem;font-weight:600}
.chip-key .dot{display:inline-block;width:12px;height:12px;border-radius:50%;margin-right:7px;vertical-align:-1px}
.dot-green{background:var(--teal)}
.dot-grey{background:#B9C6CD}
.chips{display:flex;flex-wrap:wrap;gap:10px}
.chip{display:inline-block;padding:9px 15px;border-radius:999px;font-weight:600;font-size:.93rem;text-decoration:none}
.chip-link{background:#fff;color:var(--ink);border:1.5px solid var(--teal)}
.chip-link:hover{background:var(--teal-d);color:#fff}
.chip-plain{background:#EDF2F5;color:#51616B;border:1.5px solid #C4D0D7;cursor:default}

/* checks / reviews */
.checks{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.check{background:#fff;border:1px solid var(--line);border-radius:14px;padding:24px 20px;text-align:left}
.check i{font-size:1.5rem;color:var(--teal);margin-bottom:10px;display:block}
.check h3{font-size:1.02rem}
.check p{color:var(--grey);font-size:.93rem;margin:0}
.reviews-cta{margin-top:26px}
.inline-link{font-weight:700;text-decoration:none;border-bottom:2px solid var(--tintt)}
.inline-link:hover{border-color:var(--teal)}

/* faq */
.faq details{background:#fff;border:1px solid var(--line);border-radius:12px;margin-bottom:12px;overflow:hidden}
.faq summary{cursor:pointer;padding:18px 22px;font-weight:700;color:var(--ink);list-style:none;position:relative;padding-right:52px}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"\002B";position:absolute;right:22px;top:50%;transform:translateY(-50%);color:var(--teal);font-size:1.4rem;font-weight:700}
.faq details[open] summary::after{content:"\2212"}
.faq .ans{padding:0 22px 18px}
.faq .ans p{color:var(--grey);margin:0}

/* final cta */
.band.final{background:linear-gradient(120deg,var(--ink),var(--blue-d));color:#fff;border-top:4px solid var(--teal)}
.band.final h2{color:#fff}
.band.final p{color:rgba(255,255,255,.92)}
.final-inner{display:flex;align-items:center;justify-content:space-between;gap:30px;flex-wrap:wrap}
.final-cta{display:flex;gap:12px;flex-wrap:wrap}
.band.final .btn-primary{background:#fff;color:var(--ink)}
.band.final .btn-primary:hover{background:var(--sand)}

/* footer */
.site-foot{background:var(--deep);color:#C4D6DF;padding:52px 0 0}
.foot-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1.2fr;gap:34px;padding-bottom:36px}
.foot-brand p{color:#9FB6C1;font-size:.92rem;max-width:34em}
.logo-foot{height:54px;width:auto;background:#fff;padding:8px 12px;border-radius:10px;margin-bottom:14px}
.foot-reg{font-weight:700;color:#EAF2F6!important}
.foot-col h2{color:#fff;font-size:1rem;margin:0 0 14px;letter-spacing:.02em}
.foot-col a,.foot-col p{display:block;color:#B4C8D2;text-decoration:none;font-size:.92rem;margin-bottom:9px}
.foot-col a:hover{color:#fff}
.foot-hours,.foot-addr{color:#9FB6C1!important}
.socials{display:flex;gap:10px;margin-top:16px;flex-wrap:wrap}
.socials a{width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.10);display:inline-flex;align-items:center;justify-content:center;color:#fff;text-decoration:none}
.socials a:hover{background:var(--teal)}
.foot-base{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;border-top:1px solid rgba(255,255,255,.12);padding:18px 22px}
.foot-base p{margin:0;font-size:.86rem;color:#9FB6C1}
.foot-util{display:flex;gap:18px;flex-wrap:wrap}
.foot-util a{color:#B4C8D2;text-decoration:none;font-size:.86rem}
.foot-util a:hover{color:#fff}

/* sticky mobile */
.sticky-bar{display:none;position:fixed;bottom:0;left:0;right:0;z-index:120;background:#fff;border-top:1px solid var(--line);padding:9px 12px;gap:10px;box-shadow:0 -6px 20px rgba(10,58,82,.12)}
.sticky-bar a{flex:1;display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:13px;border-radius:10px;text-decoration:none;font-weight:700;color:var(--ink);border:2px solid var(--ink)}
.sticky-bar .sticky-primary{background:var(--ink);color:#fff}

/* responsive */
@media(max-width:960px){
  .hero-grid{grid-template-columns:1fr;gap:30px}
  .cards-4{grid-template-columns:1fr 1fr}
  .steps{grid-template-columns:1fr 1fr}
  .checks{grid-template-columns:1fr 1fr}
  .split{grid-template-columns:1fr}
  .foot-grid{grid-template-columns:1fr 1fr}
  .nav{position:fixed;inset:74px 0 auto 0;background:#fff;flex-direction:column;align-items:stretch;padding:14px 18px;border-bottom:1px solid var(--line);box-shadow:var(--shadow);display:none}
  .nav.open{display:flex}
  .nav>a,.submenu-btn{padding:13px 10px;border-radius:8px}
  .navtoggle{display:inline-flex;align-items:center;justify-content:center}
  .submenu{position:static;box-shadow:none;border:0;padding:0 0 0 14px;display:block}
  .hasmenu{display:flex;flex-direction:column}
  .nav-cta{margin:8px 0 0}
  .sticky-bar{display:flex}
  body{padding-bottom:66px}
}
@media(max-width:560px){
  .eeat{grid-template-columns:1fr}
  .cards-4,.steps,.checks{grid-template-columns:1fr}
  .foot-grid{grid-template-columns:1fr}
  .trust-row{gap:10px 20px}
}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

.ic{display:inline-flex;align-items:center;justify-content:center;line-height:0}
.ic svg{width:1em;height:1em;fill:currentColor;display:block}

